package net.civeira.phylax.feature.observe.observeddashboard.domain.valueobject;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.common.exception.ConstraintException;

class HVOUnitTest {

  /**
   * @autogenerated ValueObjectGenerator
   */
  @Test
  @DisplayName("Test value object contruction for property h of observed panel ")
  void test_hvo_builder() {
    Assertions.assertThrows(ConstraintException.class, () -> HVO.tryFrom(null));
    Assertions.assertEquals(1, HVO.from(1).getH());
    Object falingInstance = new Object() {};
    Assertions.assertThrows(ConstraintException.class, () -> HVO.tryFrom(falingInstance));
    Assertions.assertEquals("[" + 1 + "]", HVO.from(1).toString());
  }
}
